// Room "P2 kitchen" (interior designer's part): inner air x39..43, z19..20, feet y2 (floor block layer y1, ceiling y5).
// The kitchen is entered from the north at the doorway (40,2..3,18) and leaves by the back door (40,2..3,21); the
// lane x40 z19..20 stays clear between them. The focal piece is the lit stove run on the north wall, facing the
// doorway: smoker, furnace and a cauldron sink. The back-wall window (x42..43) lights the table, a stair chair and a
// pantry barrel. Lanterns hang from the ceiling block at y5.
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

export function build(g) {
  // feet level y2 (z19 row first, then z20): stove run, table base, chair, pantry barrel
  layers(g, [39, 2, 19], {
    "B": ["barrel", { facing: "up" }],
    "S": ["smoker", { facing: "south", lit: "true" }],
    "F": ["furnace", { facing: "south", lit: "true" }],
    "C": "cauldron",
    "c": ["oak_stairs", { facing: "west", half: "bottom", shape: "straight", waterlogged: "false" }],
    "f": "oak_fence",
  }, [
    ["B.SFC",
     "..cfB"],
  ]);

  // y3: the table top slab (a top slab, so it stands on the fence post's top)
  layers(g, [39, 3, 19], {
    "t": ["oak_slab", { type: "top", waterlogged: "false" }],
  }, [
    [".....",
     "...t."],
  ]);

  // y4: a potted flower on the table, and a hanging lantern over the stove (hangs from the ceiling block at y5)
  layers(g, [39, 4, 19], {
    "L": ["lantern", { hanging: "true" }],
    "p": "potted_poppy",
  }, [
    ["..L..",
     "...p."],
  ]);
}

